// ─── File: EventSourcingDemo.java ───
// This single file contains multiple top-level package-private classes for a runnable demo.
// In a real project each class lives in its own file under the packages shown above.
package com.bank.eventsourcing;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class EventSourcingDemo {

    private static final Logger log = Logger.getLogger("EventSourcing");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        EventStore store = new EventStore();

        // Command side: open Rajesh's account and perform a transfer to Priya.
        Account rajesh = new Account("SAV2001");
        rajesh.open("Rajesh Kumar", new BigDecimal("1000000"));
        rajesh.debit(new BigDecimal("50000"), "Transfer to Priya CUR3001");
        rajesh.credit(new BigDecimal("12000"), "Quarterly interest");

        // Persist the NEW uncommitted events to the append-only store.
        store.append("SAV2001", rajesh.getUncommittedEvents());
        log.info(() -> "Persisted " + rajesh.getUncommittedEvents().size()
                + " events for SAV2001");
        rajesh.markCommitted();

        // Read side: rehydrate a FRESH Account purely from stored events.
        Account rebuilt = Account.rehydrate("SAV2001", store.load("SAV2001"));
        log.info(() -> "Rehydrated balance for SAV2001 = Rs." + rebuilt.getBalance());

        // Snapshot: capture current state so future loads can skip old events.
        Snapshot snap = Snapshot.of(rebuilt.getAccountId(),
                rebuilt.getVersion(), rebuilt.getBalance());
        log.info(() -> "Snapshot taken at version " + snap.version()
                + " balance Rs." + snap.balance());
    }
}

// ─── Would be in event/AccountEvent.java ───
sealed interface AccountEvent permits AccountOpened, MoneyDebited, MoneyCredited {
    Instant occurredAt();
}

// ─── Would be in event/AccountOpened.java ───
record AccountOpened(String accountId, String holder,
                     BigDecimal openingBalance, Instant occurredAt)
        implements AccountEvent { }

// ─── Would be in event/MoneyDebited.java ───
record MoneyDebited(BigDecimal amount, String reason, Instant occurredAt)
        implements AccountEvent { }

// ─── Would be in event/MoneyCredited.java ───
record MoneyCredited(BigDecimal amount, String reason, Instant occurredAt)
        implements AccountEvent { }

// ─── Would be in domain/Account.java ───
// The aggregate. Commands raise events; apply() mutates in-memory state.
class Account {
    private final String accountId;
    private String holder;
    private BigDecimal balance = BigDecimal.ZERO;
    private int version = 0;
    private final List<AccountEvent> uncommitted = new ArrayList<>();

    Account(String accountId) { this.accountId = accountId; }

    // ---- Command handlers: validate, then raise an event ----
    void open(String holder, BigDecimal opening) {
        if (version != 0) throw new IllegalStateException("Account already opened");
        raise(new AccountOpened(accountId, holder, opening, Instant.now()));
    }

    void debit(BigDecimal amount, String reason) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient funds in " + accountId);
        raise(new MoneyDebited(amount, reason, Instant.now()));
    }

    void credit(BigDecimal amount, String reason) {
        raise(new MoneyCredited(amount, reason, Instant.now()));
    }

    // raise = record new event + apply it + bump version
    private void raise(AccountEvent e) {
        apply(e);
        uncommitted.add(e);
    }

    // apply = the ONLY place that mutates state, used for both new and replayed events
    private void apply(AccountEvent e) {
        if (e instanceof AccountOpened o) {
            this.holder = o.holder();
            this.balance = o.openingBalance();
        } else if (e instanceof MoneyDebited d) {
            this.balance = this.balance.subtract(d.amount());
        } else if (e instanceof MoneyCredited c) {
            this.balance = this.balance.add(c.amount());
        }
        this.version++;
    }

    // Rebuild state from the stored log — the essence of Event Sourcing.
    static Account rehydrate(String accountId, List<AccountEvent> history) {
        Account a = new Account(accountId);
        for (AccountEvent e : history) a.apply(e);
        return a;
    }

    List<AccountEvent> getUncommittedEvents() { return List.copyOf(uncommitted); }
    void markCommitted() { uncommitted.clear(); }
    BigDecimal getBalance() { return balance; }
    int getVersion() { return version; }
    String getAccountId() { return accountId; }
}

// ─── Would be in store/EventStore.java ───
// Append-only log keyed by aggregate id. In production this is Kafka,
// EventStoreDB, or an append-only table in PostgreSQL.
class EventStore {
    private final Map<String, List<AccountEvent>> streams = new ConcurrentHashMap<>();

    void append(String aggregateId, List<AccountEvent> events) {
        streams.computeIfAbsent(aggregateId, k -> new ArrayList<>()).addAll(events);
    }

    List<AccountEvent> load(String aggregateId) {
        return List.copyOf(streams.getOrDefault(aggregateId, List.of()));
    }
}

// ─── Would be in snapshot/Snapshot.java ───
record Snapshot(String accountId, int version, BigDecimal balance) {
    static Snapshot of(String id, int version, BigDecimal balance) {
        return new Snapshot(id, version, balance);
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
